class Solution:
    def numTilings(self, n: int) -> int:
        if n <= 1:
            return 1
        two_back, full, gap = 1, 1, 0
        modulus = 1_000_000_007
        for _ in range(2, n + 1):
            next_full = (full + two_back + 2 * gap) % modulus
            gap = (gap + two_back) % modulus
            two_back, full = full, next_full
        return full
